/**
 * The starter templates `sproutboat init --template <name>` writes.
 *
 * The sources are the projects in `templates/` at the root of this repository, which CI runs. They are embedded in
 * the CLI as text (`src/templates-embedded.ts`, generated by `bun run templates:embed`) because the shipped CLI is one
 * compiled executable with no files beside it. `hello` is the original starter, written by `init.ts`, and stays the
 * default.
 */
import { EMBEDDED_TEMPLATES } from "./templates-embedded";
import { jsonObject, parseJsonValue } from "./json";
import { planPackageJson } from "./init-package";

export const DEFAULT_TEMPLATE = "hello";
const HELLO_DESCRIPTION = "The smallest handler: one fetch in JavaScript, no bindings (the default)";

export type TemplateInfo = { name: string; description: string };
export type TemplateFile = { path: string; content: string };

/** What to run first, after installing, for a template whose dev server needs more than `dev` (a package.json script). */
const FIRST_RUN = new Map([["api-d1", "db:migrate"]]);

export const firstRunScript = (template: string): string | undefined => FIRST_RUN.get(template);
export const firstRunTemplates = (): string[] => [...FIRST_RUN.keys()];

export function listTemplates(): TemplateInfo[] {
  return [
    { name: DEFAULT_TEMPLATE, description: HELLO_DESCRIPTION },
    ...Object.entries(EMBEDDED_TEMPLATES).map(([name, { description }]) => ({ name, description })),
  ];
}

export const isTemplate = (name: string): boolean =>
  name === DEFAULT_TEMPLATE || Object.hasOwn(EMBEDDED_TEMPLATES, name);

/** Every file of a template for a project called `name`: its own, with the template's name replaced by the project's. */
export function templateFiles(template: string, name: string, cliVersion: string): TemplateFile[] {
  const source = EMBEDDED_TEMPLATES[template];
  if (!source) throw new Error(`no embedded template "${template}"`);
  return Object.entries(source.files).map(([path, content]) => {
    if (path === "sproutboat.jsonc")
      return { path, content: content.replace(/("name"\s*:\s*")[^"]*(")/, `$1${name}$2`) };
    if (path === "package.json") {
      const pkg = jsonObject(parseJsonValue(content));
      if (!pkg) throw new Error(`templates/${template}/package.json is not an object`);
      // The template's own devDependencies stay; `sproutboat` is added at this CLI's version, as for the hello starter.
      return {
        path,
        content: planPackageJson(name, `${JSON.stringify({ ...pkg, name }, null, 2)}\n`, cliVersion).text,
      };
    }
    return { path, content };
  });
}
